public class StackTraceNavigatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String TRACE = String.join("\n",
            "java.lang.NullPointerException: name is null",
            "    at com.shop.order.OrderService.total(OrderService.java:42)",
            "    at com.shop.web.CartController.show(CartController.java:17)",
            "    at org.springframework.web.Dispatcher.handle(Dispatcher.java:88)",
            "Caused by: java.lang.IllegalStateException",
            "    at com.shop.order.Cart.items(Cart.java:9)");

    static int size(java.util.List<String> frames) {
        return frames == null ? -1 : frames.size();
    }

    static String at(java.util.List<String> frames, int index) {
        if (frames == null || index < 0 || index >= frames.size()) {
            return "<no such frame>";
        }
        return frames.get(index);
    }

    public static void main(String[] args) {
        check("exceptionType", "java.lang.NullPointerException",
                StackTraceNavigator.exceptionType(TRACE));
        check("exceptionType with no message", "java.io.IOException",
                StackTraceNavigator.exceptionType("java.io.IOException\n    at A.b(A.java:1)"));
        check("exceptionType of an empty trace", "", StackTraceNavigator.exceptionType(""));
        check("frame count (Caused by and message excluded)", 4,
                size(StackTraceNavigator.frames(TRACE)));
        check("first frame is trimmed", "at com.shop.order.OrderService.total(OrderService.java:42)",
                at(StackTraceNavigator.frames(TRACE), 0));
        check("last frame comes after Caused by", "at com.shop.order.Cart.items(Cart.java:9)",
                at(StackTraceNavigator.frames(TRACE), 3));
        check("deepest application frame",
                "at com.shop.order.OrderService.total(OrderService.java:42)",
                StackTraceNavigator.deepestFrameIn(TRACE, "com.shop"));
        check("deepest frame of a narrower package",
                "at com.shop.web.CartController.show(CartController.java:17)",
                StackTraceNavigator.deepestFrameIn(TRACE, "com.shop.web"));
        check("no matching package", "", StackTraceNavigator.deepestFrameIn(TRACE, "com.other"));
        check("frames of a message-only trace", 0,
                size(StackTraceNavigator.frames("java.lang.Error: boom")));
        finish();
    }
}

