public class StackTraceNavigator {

    public static String exceptionType(String trace) {
        String[] lines = trace.split("\n", -1);
        String first = lines[0].trim();
        int colon = first.indexOf(':');
        if (colon < 0) {
            return first;
        }
        return first.substring(0, colon).trim();
    }

    public static java.util.List<String> frames(String trace) {
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String line : trace.split("\n", -1)) {
            String text = line.trim();
            if (text.startsWith("at ")) {
                result.add(text);
            }
        }
        return result;
    }

    public static String deepestFrameIn(String trace, String prefix) {
        for (String frame : frames(trace)) {
            String target = frame.substring(3).trim();
            if (target.startsWith(prefix)) {
                return frame;
            }
        }
        return "";
    }
}
